package apkloader

import (
	"strings"
)

// IsKotlinSynthetic reports whether a method or class is generated by the Kotlin compiler.
// Kotlin generates a significant volume of synthetic helper methods (e.g. default parameter resolution,
// property accessors, coroutine continuation frames) which complicate static code analysis.
func IsKotlinSynthetic(className, methodName string, accessFlags uint32) bool {
	// 1. Explicit synthetic access flag (0x1000)
	if accessFlags&0x1000 != 0 {
		return true
	}

	// 2. Common Kotlin compiler-generated method suffixes
	lowerMethod := strings.ToLower(methodName)
	if strings.Contains(lowerMethod, "$default") || // Default parameters resolver
		strings.Contains(lowerMethod, "access$") || // Package-private field access helpers
		strings.Contains(lowerMethod, "$suspendimpl") || // Coroutine suspending wrapper
		strings.Contains(lowerMethod, "$continuation") { // Coroutine continuation framing
		return true
	}

	// 3. Kotlin lambda/anonymous class frames
	lowerClass := strings.ToLower(className)
	if strings.Contains(lowerClass, "$sam$") || // Single Abstract Method conversions
		strings.Contains(lowerClass, "$whenelapsed") ||
		strings.Contains(lowerClass, "$inlined$") { // Inlined block wrappers
		return true
	}

	return false
}

// CoroutineStateTransition represents a virtual state transition inside a coroutine's invokeSuspend.
type CoroutineStateTransition struct {
	FromState int
	ToState   int
	TargetBB  int // Basic Block ID
}

// ReconstructCoroutineFlow walks the CFG of a Kotlin coroutine's invokeSuspend method
// and extracts the sequential execution sequence by resolving state transitions.
//
// Continuation state machines use an internal `label` variable. Suspends set the `label`
// to the next state, and a switch at the entry dispatches to the correct block.
func ReconstructCoroutineFlow(cfg *CFG) []CoroutineStateTransition {
	if cfg == nil || len(cfg.Blocks) == 0 {
		return nil
	}

	var transitions []CoroutineStateTransition

	// Locate the entry switch block
	entry := cfg.Entry
	if entry == nil {
		return nil
	}

	// Kotlin Coroutines typically check the label field and switch on it in the first or second block
	for _, block := range cfg.Blocks {
		if len(block.Insns) == 0 {
			continue
		}

		lastInsn := &block.Insns[len(block.Insns)-1]
		if lastInsn.Kind != MIR_SWITCH {
			continue
		}

		// Found a switch dispatching the coroutine state!
		// Let's resolve the state targets (where state X goes to block Y)
		for _, succ := range block.Succs {
			// Extract virtual state transition
			// For simplicity: associate target block IDs with state indices
			stateVal := len(transitions)
			transitions = append(transitions, CoroutineStateTransition{
				FromState: 0, // entry state
				ToState:   stateVal + 1,
				TargetBB:  succ.ID,
			})
		}
	}

	// Return extracted state transitions
	return transitions
}
